ALTER TABLE public.departments ADD COLUMN manager_record_today boolean NOT NULL DEFAULT true, ADD COLUMN manager_correct_past boolean NOT NULL DEFAULT true, ADD COLUMN teacher_record_today boolean NOT NULL DEFAULT true, ADD COLUMN teacher_correct_past boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.can_record_attendance(_user uuid, _class uuid, _date date) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _date<=CURRENT_DATE AND (public.has_role(_user,'admin') OR EXISTS (SELECT 1 FROM public.classes c JOIN public.departments d ON d.id=c.department_id JOIN public.department_memberships m ON m.department_id=d.id WHERE c.id=_class AND m.user_id=_user AND CASE WHEN m.role='manager' THEN CASE WHEN _date=CURRENT_DATE THEN d.manager_record_today ELSE d.manager_correct_past END ELSE CASE WHEN _date=CURRENT_DATE THEN d.teacher_record_today ELSE d.teacher_correct_past END END)) $$;
CREATE TABLE public.ai_permission_review_state (id text PRIMARY KEY CHECK(id='permission-review'), blocked boolean NOT NULL DEFAULT false, reason text, status integer, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_permission_review_state TO service_role;
ALTER TABLE public.ai_permission_review_state ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.ai_permission_review_state IS 'Durable terminal AI access denial. Only privileged server handlers may read or change it after authenticating school administrators.';